import{_ as e,o,c as n,a1 as s}from"./chunks/framework.DdbKPUhY.js";const p=JSON.parse('{"title":"WebSocket API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/websocket-api.md","filePath":"spec/websocket-api.md"}'),r={name:"spec/websocket-api.md"};function a(i,t,c,l,d,h){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="websocket-api-spec" tabindex="-1">WebSocket API Spec <a class="header-anchor" href="#websocket-api-spec" aria-label="Permalink to &quot;WebSocket API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The WebSocket module implements RFC 6455 WebSocket protocol support. It handles the HTTP upgrade handshake, frame encoding/decoding, ping/pong, and connection management.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-ws-connection-create" tabindex="-1">uvhttp_ws_connection_create <a class="header-anchor" href="#uvhttp-ws-connection-create" aria-label="Permalink to &quot;uvhttp_ws_connection_create&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>struct uvhttp_ws_connection* uvhttp_ws_connection_create(int fd, mbedtls_ssl_context* ssl, int is_server, const uvhttp_config_t* config)</code></li><li><strong>Purpose</strong>: Create a WebSocket connection</li><li><strong>Preconditions</strong>: <code>fd</code> must be a valid socket. <code>is_server</code> indicates if this is the server side.</li><li><strong>Postconditions</strong>: Returns a valid ws_connection with CONNECTING state.</li><li><strong>Error conditions</strong>: Returns NULL on allocation failure.</li><li><strong>Thread safety</strong>: Not thread-safe.</li><li><strong>Feature gate</strong>: <code>UVHTTP_FEATURE_WEBSOCKET</code></li></ul><h3 id="uvhttp-ws-connection-free" tabindex="-1">uvhttp_ws_connection_free <a class="header-anchor" href="#uvhttp-ws-connection-free" aria-label="Permalink to &quot;uvhttp_ws_connection_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_ws_connection_free(struct uvhttp_ws_connection* conn)</code></li><li><strong>Purpose</strong>: Free a WebSocket connection</li><li><strong>Preconditions</strong>: <code>conn</code> can be NULL (no-op).</li><li><strong>Postconditions</strong>: All resources are freed.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-ws-send-frame" tabindex="-1">uvhttp_ws_send_frame <a class="header-anchor" href="#uvhttp-ws-send-frame" aria-label="Permalink to &quot;uvhttp_ws_send_frame&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_ws_send_frame(uvhttp_context_t* context, struct uvhttp_ws_connection* conn, const uint8_t* data, size_t len, uvhttp_ws_opcode_t opcode)</code></li><li><strong>Purpose</strong>: Send a raw WebSocket frame</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid and in OPEN state.</li><li><strong>Postconditions</strong>: Frame is sent to the client.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: conn is NULL or state is not OPEN</li><li>Write error from underlying socket/SSL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-ws-send-text-uvhttp-ws-send-binary" tabindex="-1">uvhttp_ws_send_text / uvhttp_ws_send_binary <a class="header-anchor" href="#uvhttp-ws-send-text-uvhttp-ws-send-binary" aria-label="Permalink to &quot;uvhttp_ws_send_text / uvhttp_ws_send_binary&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_ws_send_text(uvhttp_context_t* context, struct uvhttp_ws_connection* conn, const char* text, size_t len)</code> / <code>uvhttp_error_t uvhttp_ws_send_binary(uvhttp_context_t* context, struct uvhttp_ws_connection* conn, const uint8_t* data, size_t len)</code></li><li><strong>Purpose</strong>: Send a text or binary message</li><li><strong>Preconditions</strong>: Same as <code>uvhttp_ws_send_frame</code></li><li><strong>Postconditions</strong>: Message is sent as a complete WebSocket frame.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-ws-close" tabindex="-1">uvhttp_ws_close <a class="header-anchor" href="#uvhttp-ws-close" aria-label="Permalink to &quot;uvhttp_ws_close&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_ws_close(uvhttp_context_t* context, struct uvhttp_ws_connection* conn, int code, const char* reason)</code></li><li><strong>Purpose</strong>: Initiate WebSocket close handshake</li><li><strong>Preconditions</strong>: <code>conn</code> must be valid.</li><li><strong>Postconditions</strong>: Close frame is sent. State transitions to CLOSING.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: conn is NULL or stale</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-server-ws-broadcast" tabindex="-1">uvhttp_server_ws_broadcast <a class="header-anchor" href="#uvhttp-server-ws-broadcast" aria-label="Permalink to &quot;uvhttp_server_ws_broadcast&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_server_ws_broadcast(uvhttp_server_t* server, const char* path, const char* data, size_t len)</code></li><li><strong>Purpose</strong>: Send a message to all WebSocket clients on a path</li><li><strong>Preconditions</strong>: <code>server</code> must be valid with connection management enabled.</li><li><strong>Postconditions</strong>: Message is sent to all matching connections.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="websocket-states" tabindex="-1">WebSocket States <a class="header-anchor" href="#websocket-states" aria-label="Permalink to &quot;WebSocket States&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONNECTING → OPEN → CLOSING → CLOSED</span></span></code></pre></div><h2 id="frame-types" tabindex="-1">Frame Types <a class="header-anchor" href="#frame-types" aria-label="Permalink to &quot;Frame Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opcode</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>0x0</td><td>Continuation</td><td>Continuation of fragmented message</td></tr><tr><td>0x1</td><td>Text</td><td>UTF-8 text message</td></tr><tr><td>0x2</td><td>Binary</td><td>Binary message</td></tr><tr><td>0x8</td><td>Close</td><td>Close handshake</td></tr><tr><td>0x9</td><td>Ping</td><td>Ping frame</td></tr><tr><td>0xA</td><td>Pong</td><td>Pong frame</td></tr></tbody></table><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Handshake</strong>: WebSocket upgrade is initiated via HTTP Upgrade request. The server responds with 101 Switching Protocols.</p></li><li><p><strong>Frame masking</strong>: Client frames must be masked. Server frames are not masked (per RFC 6455).</p></li><li><p><strong>Fragmentation</strong>: Large messages can be fragmented into multiple frames. The FIN bit indicates the last frame.</p></li><li><p><strong>Ping/pong</strong>: The server sends pings periodically (configurable interval). If no pong is received within the timeout, the connection is closed.</p></li><li><p><strong>Connection management</strong>: The server tracks WebSocket connections in a linked list. Connections are checked for timeout periodically.</p></li><li><p><strong>Broadcast</strong>: Messages can be broadcast to all connections on a specific path.</p></li></ol><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Connection creation and destruction</li><li>Frame encoding/decoding</li><li>Text and binary message send</li><li>Close handshake</li><li>Broadcast to multiple connections</li><li>Connection timeout detection</li><li>Ping/pong cycle</li><li>NULL parameter handling</li><li>Memory cleanup (no leaks on free)</li></ul>',24)])])}const _=e(r,[["render",a]]);export{p as __pageData,_ as default};
